"""R08b §0.1 item 2: every report table is generated here from the persisted outputs. Writes R08b/tables/*.md with a
provenance comment, plus tables/sources.json."""
from __future__ import annotations
import json, os, sys
import numpy as np, pandas as pd
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import r08b_common as RB, r04_common as C4
TAB = RB.TABLES; os.makedirs(TAB, exist_ok=True); SRC = {}
def emit(name, src, lines): SRC[name] = src; open(f"{TAB}/{name}.md", "w").write(f"<!-- generated by report_tables_r08b.py from {src} -->\n" + "\n".join(lines) + "\n"); print(f"wrote tables/{name}.md")
def f(x, d=3, sign=False):
    if x is None or (isinstance(x, float) and not np.isfinite(x)): return "—"
    if isinstance(x, (int, np.integer)): return f"{x:,}"
    return f"{x:+.{d}f}" if sign else f"{x:.{d}f}"
def ci(r): return f"{f(r['value'])} [{f(r['ci95'][0])}, {f(r['ci95'][1])}] (n {r['n_units']})" if r.get("n_units") else "—"
def cmp2(c):
    if not c.get("n_units"): return "— | — | — | —"
    return f"{c['diff_median']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] | {c['paired_median']:+.3f} [{c['paired_ci95'][0]:+.3f}, {c['paired_ci95'][1]:+.3f}] | {c['units_a_better']} / {c['units_b_better']} of {c['n_units']} | {c['sign_test_p_one_sided']:.3f}"
star = lambda u: f"{u}{' *' if u in RB.SIX else ''}"
HDR2 = "Δ of medians [CI] | paired median Δ [CI] | better / worse | p"

# ---- blind calls joined to the key
key = {r["code"]: r for r in json.load(open(f"{RB.R8.FIGURES}/key/figset_A_key.json"))["order"]}; calls = pd.read_csv(f"{RB.REP}/R08_figset_A_calls_steve_2026-10-09.csv").fillna("")
calls["pair"] = calls.code.map(lambda c: key[c]["pair"]); calls["unit"] = calls.code.map(lambda c: key[c]["unit"]); calls["six"] = calls.unit.isin(RB.SIX)
calls["crit"] = calls.apply(lambda r: ", ".join(k for k, v in (("a", r.a_stripes), ("b", r.b_ribbing), ("c", r.c_halos)) if v == "yes") or "none", axis=1)
L = ["| code | unit | pair | relief | criteria (a stripes, b ribbing, c halos) | dominant | call (Steve, condensed) |", "|---|---|---|---|---|---|---|"]
for r in calls.sort_values(["unit", "pair"]).itertuples(): L.append(f"| {r.code} | {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.pair} | {r.relief} | {r.crit} | {r.dominant} | {r.call_text} |")
s6 = calls[calls.six]; so = calls[~calls.six]
L.append(f"| **six** | 6 units / {len(s6)} pairs | | | with a, b or c: {int((s6.crit != 'none').sum())} / {len(s6)}; relief-only: {int((s6.crit == 'none').sum())} | artifact-dominant: {', '.join(s6[s6.dominant == 'artifact'].pair)} | |")
L.append(f"| **other (EW0207 included)** | 11 units / {len(so)} pairs | | | relief-only: {int((so.crit == 'none').sum())} / {len(so)} | artifact-dominant: {int((so.dominant == 'artifact').sum())} | |")
emit("blind_calls_joined", "R08_figset_A_calls_steve_2026-10-09.csv joined to R08/figures/key/figset_A_key.json", L)

# ---- interior tiles
PI = json.load(open(f"{RB.OUT_INT}/pairs.json")); PP = pd.DataFrame(PI["pairs"]); TI = pd.read_parquet(f"{RB.OUT_INT}/tiles_interior.parquet")
L = ["| unit | pair | lr_native (m) | hr_res (m) | D1 (px / m) | D2 (px / m) | tiles | interior D1 (fraction) | interior D2 (fraction) | median A_fine all / D1 / D2 (m) |", "|---|---|---|---|---|---|---|---|---|---|"]
for r in PP.sort_values(["unit", "pair"]).itertuples(): L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.pair} | {r.lr_native_m:.1f} | {r.hr_res_m:.2f} | {r.D1_px} / {r.D1_m:.0f} | {r.D2_px} / {r.D2_m:.0f} | {r.n_tiles} | {r.n_interior_D1} ({r.frac_interior_D1:.2f}) | {r.n_interior_D2} ({r.frac_interior_D2:.2f}) | {r.A_fine_median_all:.4f} / {f(r.A_fine_median_D1, 4)} / {f(r.A_fine_median_D2, 4)} |")
emit("interior_per_pair", "interior/pairs.json (interior_r08b.py)", L)
U = TI.groupby("unit").agg(n_tiles=("tile_id", "size"), n_D1=("interior_D1", "sum"), n_D2=("interior_D2", "sum"), A_all=("A_fine", "median")).reset_index()
U["A_D1"] = TI[TI.interior_D1].groupby("unit").A_fine.median().reindex(U.unit).values; U["A_D2"] = TI[TI.interior_D2].groupby("unit").A_fine.median().reindex(U.unit).values
L = ["| unit | pairs | tiles | interior D1 (fraction) | interior D2 (fraction) | median A_fine all (m) | D1 | D2 | D1 / all |", "|---|---|---|---|---|---|---|---|---|"]
for r in U.itertuples(): L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {len(C4.UNITS.get(r.unit, [1]))} | {r.n_tiles:,} | {int(r.n_D1):,} ({r.n_D1 / r.n_tiles:.2f}) | {int(r.n_D2):,} ({r.n_D2 / r.n_tiles:.2f}) | {r.A_all:.4f} | {f(r.A_D1, 4)} | {f(r.A_D2, 4)} | {f(r.A_D1 / r.A_all, 2)} |")
for name, uset in RB.UNIT_SETS.items():
    d = TI[TI.unit.isin(uset)]; uu = U[U.unit.isin(uset)]
    L.append(f"| **{name}** | {sum(len(C4.UNITS[u]) for u in uset)} | {len(d):,} | {int(d.interior_D1.sum()):,} ({d.interior_D1.mean():.2f}; unit-median fraction {np.median(uu.n_D1 / uu.n_tiles):.2f}) | {int(d.interior_D2.sum()):,} ({d.interior_D2.mean():.2f}; {np.median(uu.n_D2 / uu.n_tiles):.2f}) | unit-median {uu.A_all.median():.4f} | {uu.A_D1.median():.4f} | {uu.A_D2.median():.4f} | unit-median ratio {np.nanmedian(uu.A_D1 / uu.A_all):.2f} |")
emit("interior_per_unit", "interior/tiles_interior.parquet (interior_r08b.py)", L)

# ---- scores
S = json.load(open(f"{RB.OUT_SCORES}/scores.json")); PAIRED = [("GBT_ship_A_fine", "ref_s_lr"), ("V2_seedavg", "GBT_ship_A_fine"), ("V2_seedavg", "ref_s_lr"), ("P-V1_seedavg", "GBT_ship_A_fine"), ("GBT_ship_dropEV_A_fine", "GBT_ship_A_fine")]; EL = json.load(open(f"{RB.OUT_SCORES}/eligibility.json")); PREDS = S["predictors"]; FAM = S["families"]
L = ["| level | pairs dropped (target eligibility, < 10 interior tiles) | units dropped |", "|---|---|---|"]
for s in ("D1", "D2"): L.append(f"| {s} | {len(EL['drops'][s]['pairs'])}: " + ", ".join(f"{p['pair']} ({p['unit']}, {p['n_tiles_ok']} tiles)" for p in EL["drops"][s]["pairs"]) + f" | {len(EL['drops'][s]['units'])}: {', '.join(EL['drops'][s]['units']) or 'none'} |")
emit("eligibility_drops", "scores/eligibility.json:drops (score_r08b.py)", L)
for name in RB.UNIT_SETS:
    L = [f"| family | predictor | all tiles | interior D1 | interior D2 | D1 − all: {HDR2} | D2 − all: paired median Δ [CI] |", "|---|---|---|---|---|---|---|---|---|---|"]
    for fam, ps in FAM.items():
        for p in ps:
            m = S["median"][name]; c1 = S["interior_vs_all"][name]["D1"][p]; c2 = S["interior_vs_all"][name]["D2"][p]
            L.append(f"| {fam} | {p} | {ci(m['all'][p])} | {ci(m['D1'][p])} | {ci(m['D2'][p])} | {cmp2(c1)} | {f(c2.get('paired_median'), sign=True)} [{f(c2.get('paired_ci95', [np.nan, np.nan])[0], sign=True)}, {f(c2.get('paired_ci95', [np.nan, np.nan])[1], sign=True)}] |")
    emit(f"scores_{name}", f"scores/scores.json:median,interior_vs_all[{name}] (score_r08b.py)", L)
    uset = RB.UNIT_SETS[name]; L = ["| predictor | " + " | ".join(f"{star(u)} all / D1" for u in uset) + " |", "|---|" + "---|" * len(uset)]
    for p in PREDS: L.append(f"| {p} | " + " | ".join(f"{f(S['per_unit']['all'][p].get(u, np.nan), 2, True)} / {f(S['per_unit']['D1'][p].get(u, np.nan), 2, True)}" for u in uset) + " |")
    emit(f"per_unit_{name}", f"scores/scores.json:per_unit (score_r08b.py), units of {name}", L)
L = [f"| unit set | subset | comparison | {HDR2} |", "|---|---|---|---|---|---|---|"]
for name in RB.UNIT_SETS:
    for s in ("D1", "all", "D2"):
        for a, b in PAIRED: L.append(f"| {name} | {s} | {a} − {b} | {cmp2(S['paired'][name][s][f'{a}-{b}'])} |")
emit("paired_comparisons", "scores/scores.json:paired (score_r08b.py)", L)
L = [f"| unit set | subset | feasible pairs | within-site | held-out GBT_ship (same pairs) | within − GBT_ship: {HDR2} |", "|---|---|---|---|---|---|---|---|---|"]
for s in ("D1", "all", "D2"):
    for name in RB.UNIT_SETS: w = S["within_vs_gbt"][s][name]; L.append(f"| {name} | {s} | {w['n_pairs']} | {ci(w['within'])} | {ci(w['gbt_same_pairs'])} | {cmp2(w['cmp'])} |")
emit("within_site", "scores/scores.json:within_vs_gbt (score_r08b.py)", L)
rg = S["reading_guide"]
emit("reading_guide", "scores/scores.json:reading_guide (score_r08b.py)", ["| predictor (primary ten, D1 − all) | paired median Δ [CI] | material (Δ ≤ −0.10 or CI upper < −0.05) |", "|---|---|---|"] + [f"| {p} | {rg[p]['paired_median']:+.3f} [{rg[p]['paired_ci95'][0]:+.3f}, {rg[p]['paired_ci95'][1]:+.3f}] | {'yes' if rg[p]['material'] else 'no'} |" for p in ("GBT_ship_A_fine", "ref_s_lr")])
ew = S["EW0207"]; preds_ew = list(ew["all"]["rho"]); L = ["| predictor | all tiles (n " + f"{ew['all']['n_tiles']:,}) | D1 (n {ew['D1']['n_tiles']:,}) | D2 (n {ew['D2']['n_tiles']:,}) |", "|---|---|---|---|"]
for p in preds_ew: L.append(f"| {p} | {f(ew['all']['rho'][p], sign=True)} | {f(ew['D1']['rho'][p], sign=True)} | {f(ew['D2']['rho'][p], sign=True)} |")
emit("EW0207", "scores/scores.json:EW0207 (score_r08b.py)", L)
# ---- ledger of dropped tiles / pairs / units
n_all = len(TI); L = ["| stage | item | count | reason |", "|---|---|---|---|", f"| §2 | tiles not interior at D1 | {int((~TI.interior_D1).sum()):,} of {n_all:,} | < 95 % of joint-valid px at distance ≥ D1 from an invalid px |", f"| §2 | tiles not interior at D2 | {int((~TI.interior_D2).sum()):,} of {n_all:,} | same at D2 = 2 D1 |"]
for s in ("D1", "D2"): L.append(f"| §3 | pairs ineligible at {s} | {len(EL['drops'][s]['pairs'])} of 38 | < 10 interior tiles (see the eligibility table) |"); L.append(f"| §3 | units without an eligible pair at {s} | {len(EL['drops'][s]['units'])} of 16 | {', '.join(EL['drops'][s]['units']) or '—'} |")
L.append(f"| §3 | within-site | scored on its {S['within_vs_gbt']['D1']['all16']['n_pairs']} feasible-and-eligible pairs at D1 ({S['within_vs_gbt']['all']['all16']['n_pairs']} on all tiles) | R08 feasibility (H1) and the interior eligibility |"); L.append("| §3 | sigma_m_R02 | native 7 units only | R02 model coverage |"); L.append("| §3 | ref_rsd128 | usable-product units only | ship products unavailable elsewhere |")
emit("ledger", "interior/tiles_interior.parquet, scores/eligibility.json, scores/scores.json", L)
json.dump(SRC, open(f"{TAB}/sources.json", "w"), indent=1); print("wrote tables/sources.json")
